breach.segment:
// At least 5 one-minute samples in the window
WHERE COALESCE(deadlock_samples, 0) >= 5 OR COALESCE(lock_timeout_samples, 0) >= 5
// Per-minute rates: summed deltas divided by the minutes actually reported (robust to gaps and duplicate points).
// Each count needs at least 5 samples of its own, so a single late sample of one count can't decide the alert.
| EVAL deadlocks_per_min = CASE(deadlock_samples >= 5, TO_DOUBLE(deadlocks) / deadlock_samples, 0.0),
       lock_timeouts_per_min = CASE(lock_timeout_samples >= 5, TO_DOUBLE(lock_timeouts) / lock_timeout_samples, 0.0)
| EVAL lock_failures_per_min = deadlocks_per_min + lock_timeouts_per_min
// Threshold: on average at least 1 failed statement per minute across the window
| WHERE lock_failures_per_min >= 1.0
| EVAL lock_failures_per_min = ROUND(lock_failures_per_min, 2),
       deadlocks_per_min = ROUND(deadlocks_per_min, 2),
       lock_timeouts_per_min = ROUND(lock_timeouts_per_min, 2)
| SORT lock_failures_per_min DESC, database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, lock_failures_per_min, deadlocks_per_min, lock_timeouts_per_min
